import { useEffect, useState, useSyncExternalStore, type ChangeEvent } from "react";
import { getSettings, setSettings, type Settings as SettingsShape } from "../lib/settings";
import type { Level } from "../lib/types";
import * as store from "../srs/store";
import { gemma, MODEL_FILE, MODEL_LABEL, MODEL_LICENCE, type GemmaStatus } from "../offline/gemma";
import { useInstallPrompt } from "../pwa/install";
import { useAuth } from "../auth/auth";
import { useBackupStatus, type BackupStatus } from "../sync/backup";

const levels: Level[] = ["A1", "A2", "B1", "B2"];

const voices = [
  { id: "YKeBw3OV1RgpdhLh", name: "Jules" },
  { id: "biuhvu17TxVKOcyy", name: "Marius" },
  { id: "iEu63s1rhn_kegTr", name: "Gaspard" },
  { id: "YhIHaAfQ0cQPDV9R", name: "Solène" },
  { id: "FXxJ9mANRq6BCTX5", name: "Noémie" },
];

const modelUrl = (import.meta.env.VITE_GEMMA_MODEL_URL as string | undefined) || "";

function statusText(s: GemmaStatus): string {
  switch (s.state) {
    case "unavailable":
      return "not supported in this browser (needs webgpu)";
    case "absent":
      return "not installed";
    case "loading":
      return s.progress === undefined ? "loading" : `loading ${s.progress} %`;
    case "ready":
      return s.source === "bundled" ? "ready, built into the app" : "ready";
    case "error":
      return s.reason ? `error: ${s.reason}` : "error";
  }
}

function backupText(s: BackupStatus): string {
  switch (s.state) {
    case "ok": {
      if (s.lastOkAt === null) return "ready";
      const time = new Date(s.lastOkAt).toLocaleTimeString("en-GB", {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
        timeZone: "Europe/Zurich",
      });
      return `backed up ${time}`;
    }
    case "working":
      return "backing up…";
    case "error":
      return "backup failed, will retry";
    case "offline":
      return "offline, will back up later";
    case "off":
      return "ready";
  }
}

const row = "flex flex-col gap-2 rounded-[var(--radius-card)] border border-line bg-card p-4";
const control = "rounded-[var(--radius-button)] border border-line bg-card px-3 py-2";

export default function Settings() {
  const [settings, setLocal] = useState(getSettings);
  const [cleared, setCleared] = useState(false);

  function update(partial: Partial<SettingsShape>) {
    setLocal(setSettings(partial));
  }

  function clearAll() {
    if (!window.confirm("clear everything? this removes every kept phrase.")) return;
    store.clear();
    setCleared(true);
  }

  return (
    <section className="pt-safe pb-tabbar flex flex-col gap-3 px-[var(--gutter)]">
      <h1 className="text-[length:var(--text-h1)] leading-[var(--lh-h1)] font-bold">settings</h1>

      <div className={row}>
        <span className="text-muted">language</span>
        <span>french</span>
      </div>

      <label className={row}>
        <span className="text-muted">level</span>
        <select
          value={settings.level}
          onChange={(e) => update({ level: e.target.value as Level })}
          className={control}
        >
          {levels.map((l) => (
            <option key={l} value={l}>
              {l}
            </option>
          ))}
        </select>
      </label>

      <label className={row}>
        <span className="text-muted">voice</span>
        <select value={settings.voiceId} onChange={(e) => update({ voiceId: e.target.value })} className={control}>
          {voices.map((v) => (
            <option key={v.id} value={v.id}>
              {v.name}
            </option>
          ))}
        </select>
      </label>

      <label className={row}>
        <span className="text-muted">speed {settings.speed.toFixed(1)}</span>
        <input
          type="range"
          min={0.8}
          max={1.2}
          step={0.1}
          value={settings.speed}
          onChange={(e) => update({ speed: Number(e.target.value) })}
          className="accent-[var(--moss)]"
        />
      </label>

      <OnYourPhone />

      <AccountSection />

      <OfflineTutor />

      <div className={row}>
        <span className="text-muted">data</span>
        <p className="text-[length:var(--text-small)] text-muted">everything stays in this browser</p>
        <button
          type="button"
          onClick={clearAll}
          className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 text-[var(--clay)]"
        >
          clear everything
        </button>
        {cleared && <p className="text-[length:var(--text-small)] text-muted">cleared</p>}
      </div>
    </section>
  );
}

function AccountSection() {
  const { status, address, openAccount, signOut } = useAuth();
  const backup = useBackupStatus();
  const muted = "text-[length:var(--text-small)] text-muted";

  let body;
  if (status === "disabled") {
    body = <p className={muted}>sync is off in this build</p>;
  } else if (status === "loading") {
    body = <p className={muted}>checking your account…</p>;
  } else if (status === "signed_out") {
    body = (
      <>
        <p className="text-[length:var(--text-small)]">
          sign in to sync your words, scenes and conversations across devices. everything also works without an account.
        </p>
        <button
          type="button"
          onClick={openAccount}
          className="self-start rounded-[var(--radius-pill)] bg-moss px-5 py-2 font-semibold text-snow"
        >
          sign in
        </button>
      </>
    );
  } else {
    body = (
      <>
        <p data-testid="account-address">{address}</p>
        <p className={muted}>signed in</p>
        <div className="flex items-center justify-between">
          <span className="text-muted">sync</span>
          <span data-testid="sync-state">{backupText(backup)}</span>
        </div>
        <button
          type="button"
          onClick={() => void signOut()}
          className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2"
        >
          sign out
        </button>
      </>
    );
  }

  return (
    <div className={row} data-testid="account">
      <span className="text-muted">account</span>
      {body}
    </div>
  );
}

function OnYourPhone() {
  const { canInstall, install, platform, installed } = useInstallPrompt();

  let body;
  if (installed) {
    body = <p>installed. works offline.</p>;
  } else if (canInstall) {
    body = (
      <button
        type="button"
        onClick={() => void install()}
        className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2"
      >
        add to home screen
      </button>
    );
  } else if (platform === "ios") {
    body = (
      <ol className="flex flex-col gap-1 text-[length:var(--text-small)]">
        <li>open in safari</li>
        <li>tap share</li>
        <li>add to home screen</li>
      </ol>
    );
  } else {
    body = <p className="text-[length:var(--text-small)] text-muted">open this page on your phone to install it</p>;
  }

  return (
    <div className={row} data-testid="on-your-phone">
      <span className="text-muted">on your phone</span>
      {body}
    </div>
  );
}

function OfflineTutor() {
  const status = useSyncExternalStore(gemma.subscribe, gemma.status);
  const [failed, setFailed] = useState<string | null>(null);

  useEffect(() => {
    void gemma.refresh();
  }, []);

  function run(job: Promise<void>) {
    setFailed(null);
    job.catch((e: unknown) => setFailed(e instanceof Error ? e.message : "could not install"));
  }

  function onFile(e: ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (file) run(gemma.importFile(file));
  }

  function remove() {
    if (!window.confirm("remove the offline tutor? you will need to pick the file again.")) return;
    run(gemma.remove());
  }

  const busy = status.state === "loading";
  const builtIn = status.source === "bundled";
  const usable = status.state !== "unavailable" && !builtIn;
  const installed = builtIn || status.state === "ready";

  return (
    <div className={row}>
      <span className="text-muted">offline tutor</span>
      <p data-testid="offline-status">{statusText(status)}</p>
      {usable &&
        (modelUrl ? (
          <button
            type="button"
            disabled={busy}
            onClick={() => run(gemma.importUrl(modelUrl))}
            className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 disabled:opacity-50"
          >
            download
          </button>
        ) : (
          <label className="flex flex-col gap-1">
            <span className="text-[length:var(--text-small)]">choose {MODEL_FILE}</span>
            <input
              type="file"
              accept=".task"
              aria-label={`choose ${MODEL_FILE}`}
              disabled={busy}
              onChange={onFile}
              className={control}
            />
          </label>
        ))}
      {usable && (status.state === "ready" || status.state === "error") && (
        <button
          type="button"
          onClick={remove}
          className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 text-[var(--clay)]"
        >
          remove
        </button>
      )}
      {failed && <p className="text-[length:var(--text-small)] text-muted">{failed}</p>}
      {installed && (
        <p className="text-[length:var(--text-small)] text-muted">
          on-device model: {MODEL_LABEL},{" "}
          <a href={MODEL_LICENCE.url} target="_blank" rel="noreferrer" className="underline">
            {MODEL_LICENCE.name}
          </a>
        </p>
      )}
      {!builtIn && (
        <p className="text-[length:var(--text-small)] text-muted">
          when the network is gone, noé runs on gemma 4 e2b in this browser. get {MODEL_FILE} (about 2 gb) from{" "}
          <a
            href="https://huggingface.co/litert-community/gemma-4-E2B-it-litert-lm"
            target="_blank"
            rel="noreferrer"
            className="underline"
          >
            hugging face
          </a>
          . the file stays in this browser.
        </p>
      )}
    </div>
  );
}
import { useEffect, useRef, useState, type FormEvent, type KeyboardEvent } from "react";
import GlassButton from "../components/GlassButton";
import { COPY, useAuth } from "../auth/auth";

type Mode = "sign_in" | "sign_up";

function validate(address: string, password: string): string | null {
  const at = address.indexOf("@");
  if (at < 1 || !address.slice(at + 1).includes(".") || address.endsWith(".")) return "enter your email address";
  if (password.length < 8) return COPY.weak;
  return null;
}

const field = "rounded-[var(--radius-button)] border border-line bg-card px-3 py-3 text-[length:var(--text-body)]";

/** Our own sign-in sheet. Full screen above the tab bar; Escape and "not now" close it. */
export default function Account({ onClose }: { onClose: () => void }) {
  const { signIn, signUp } = useAuth();
  const [mode, setMode] = useState<Mode>("sign_in");
  const [address, setAddress] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [confirm, setConfirm] = useState(false);
  const mounted = useRef(true);
  const busy = useRef(false);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  function switchMode(next: Mode) {
    if (pending) return;
    setMode(next);
    setPassword("");
    setError(null);
  }

  async function submit(e: FormEvent) {
    e.preventDefault();
    if (busy.current) return;
    const invalid = validate(address.trim(), password);
    if (invalid) {
      setError(invalid);
      return;
    }
    busy.current = true;
    setPending(true);
    setError(null);
    const run = mode === "sign_in" ? signIn : signUp;
    const result = await run(address.trim(), password);
    busy.current = false;
    if (!mounted.current) return;
    setPending(false);
    if (result.ok) {
      setPassword("");
      onClose();
      return;
    }
    if (result.needsConfirm) {
      setPassword("");
      setConfirm(true);
      return;
    }
    if (result.existing) {
      setMode("sign_in");
      setPassword("");
    }
    setError(result.error ?? COPY.generic);
  }

  function onKeyDown(e: KeyboardEvent) {
    if (e.key === "Escape") onClose();
  }

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="account-title"
      onKeyDown={onKeyDown}
      className="fixed inset-0 z-50 overflow-y-auto bg-paper"
    >
      <div className="pt-safe mx-auto flex min-h-dvh max-w-md flex-col gap-4 px-[var(--gutter)] pb-[max(24px,env(safe-area-inset-bottom))]">
        <div className="flex justify-end pt-2">
          <GlassButton aria-label="close" onClick={onClose}>
            <span aria-hidden className="text-[20px] leading-none">×</span>
          </GlassButton>
        </div>
        <h1 id="account-title" className="text-[length:var(--text-h1)] leading-[var(--lh-h1)] font-bold">
          account
        </h1>

        {confirm ? (
          <div className="flex flex-col gap-4">
            <p role="status">{COPY.confirm}</p>
            <button
              type="button"
              onClick={() => {
                setConfirm(false);
                switchMode("sign_in");
              }}
              className="self-start rounded-[var(--radius-pill)] bg-moss px-6 py-3 font-semibold text-snow"
            >
              back to sign in
            </button>
          </div>
        ) : (
          <>
            <div role="tablist" aria-label="mode" className="flex rounded-[var(--radius-pill)] border border-line bg-card p-1">
              {(
                [
                  ["sign_in", "sign in"],
                  ["sign_up", "create account"],
                ] as const
              ).map(([m, label]) => (
                <button
                  key={m}
                  type="button"
                  role="tab"
                  aria-selected={mode === m}
                  onClick={() => switchMode(m)}
                  className={`flex-1 rounded-[var(--radius-pill)] px-3 py-2 text-[length:var(--text-callout)] ${
                    mode === m ? "bg-moss-soft font-semibold text-moss" : "text-muted"
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>

            <form noValidate onSubmit={(e) => void submit(e)} className="flex flex-col gap-3">
              <label className="flex flex-col gap-1">
                <span className="text-muted">address</span>
                <input
                  type="email"
                  name="email"
                  autoComplete="email username"
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  className={field}
                />
              </label>
              <div className="flex flex-col gap-1">
                <label htmlFor="account-password" className="text-muted">
                  password
                </label>
                <div className="flex gap-2">
                  <input
                    id="account-password"
                    type={show ? "text" : "password"}
                    name="password"
                    autoComplete={mode === "sign_in" ? "current-password" : "REDACTED"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className={`${field} min-w-0 flex-1`}
                  />
                  <button
                    type="button"
                    aria-label={show ? "hide password" : "REDACTED"}
                    onClick={() => setShow((s) => !s)}
                    className="rounded-[var(--radius-button)] border border-line bg-card px-3 text-[length:var(--text-small)] text-muted"
                  >
                    {show ? "hide" : "show"}
                  </button>
                </div>
              </div>
              {error && (
                <p role="alert" className="text-[length:var(--text-small)] text-[var(--clay)]">
                  {error}
                </p>
              )}
              <button
                type="submit"
                disabled={pending}
                aria-busy={pending}
                className="mt-2 flex items-center justify-center gap-2 rounded-[var(--radius-pill)] bg-moss px-6 py-3 font-semibold text-snow disabled:opacity-60"
              >
                {pending && (
                  <span
                    aria-hidden
                    className="h-4 w-4 rounded-[var(--radius-pill)] border-2 border-snow/40 border-t-snow motion-safe:animate-spin"
                  />
                )}
                {mode === "sign_in" ? "sign in" : "create account"}
              </button>
            </form>
          </>
        )}

        <button type="button" onClick={onClose} className="self-center px-4 py-2 text-muted">
          not now
        </button>
        <p className="text-[length:var(--text-small)] text-muted">
          optional. without an account everything stays on this phone. your words sync to a server in Zurich (Supabase).
        </p>
      </div>
    </div>
  );
}
